    internal static IEnumerable<string> Keys=>Entries.Keys;
    internal static string Text(string key) => Text(key,UiLanguage.Current);
    internal static string Text(string key,ApplicationLanguage language)
    {
        if(AiUiText.TryText(key,language,out var extra))return extra;
        key=key switch {"ai_connection_name"=>"NameError","ai_connection_fields"=>"FieldsError","ai_connection_key"=>"KeyError","ai_connection_storage"=>"StorageError","ai_connection_limit"=>"LimitError",_=>key};
        int i=language switch {ApplicationLanguage.SimplifiedChinese=>0,ApplicationLanguage.TraditionalChinese=>1,ApplicationLanguage.English=>2,ApplicationLanguage.Japanese=>3,ApplicationLanguage.Korean=>4,ApplicationLanguage.Spanish=>5,ApplicationLanguage.French=>6,ApplicationLanguage.German=>7,ApplicationLanguage.Russian=>8,_=>2};
        return Entries.TryGetValue(key,out var row)?row[i]:AiToolsText.Text(key);
    }
